/bin/zsh -lc "python3 - <<'PY'
import json
from pathlib import Path
for fn in ['coordination.json','policy.json','source.json','validation-failure.json']:
 p=Path(fn); d=json.loads(p.read_text())
 print(fn, 'bytes',p.stat().st_size, 'type',type(d).__name__)
 if isinstance(d,dict):
  print('keys:',list(d))
 elif isinstance(d,list):
  print('items:',len(d))
  for x in d:
   print({k:v for k,v in x.items() if k not in ['source_xml','source_notes_xml','sru_context']})
PY"

